	@ParameterizedTest
	@ValueSource(strings = { "local", "remote", "mixed" })
	void invalidBoundStatementPositionsProduceNoMatch(String transport) throws Exception {
		initialize(transport);
		for (String position : List.of("outer", "predicate", "graph", "innerS", "innerP")) {
			QueryBindingSet input = input();
			FedXStatementPattern pattern;
			if (position.startsWith("inner")) {
				pattern = triple();
			} else {
				StatementPattern statement = position.equals("graph")
						? new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS, Var.of("outer"),
								Var.of("predicate"), Var.of("object"), Var.of("graph"))
						: new StatementPattern(Var.of("outer"), Var.of("predicate"), Var.of("object"));
				pattern = new StatementSourcePattern(statement, info);
				sources.forEach(pattern::addStatementSource);
				input.setBinding("predicate", Q);
			}
			input.setBinding(position, VF.createLiteral("wrong RDF term kind"));
			try (var results = strategy.precompile(pattern).evaluate(input)) {
				assertThat(QueryResults.asList(results)).as(position).isEmpty();
			}
		}
	}

	@ParameterizedTest
	@ValueSource(strings = { "local", "remote", "mixed" })
	void boundTripleRefComponentRefreshesGroupMetadataAndConformsToEquality(String transport) throws Exception {
		initialize(transport, List.of(10, 11));
		TripleRefStatementPattern triple = triple();
		TripleRefJoinGroup group = group(triple);

		assertThat(group.getFreeVars()).contains("innerO");
		assertThat(group.getAssuredBindingNames()).contains("innerO");
		triple.addBoundFilter("innerO", VF.createLiteral(10));
		assertThat(group.getFreeVars()).doesNotContain("innerO");
		// Bound relational variables remain outputs; runtime restores the value after rendering it as a term.
		assertThat(group.getAssuredBindingNames()).contains("innerO");

		try (var results = strategy.evaluateTripleRefJoinGroup(group, input())) {
			assertThat(QueryResults.asList(results)).hasSize(1).allSatisfy(row -> {
				assertThat(row.getValue("innerO")).isEqualTo(VF.createLiteral(10));
				assertThat(row.getValue("outer")).isEqualTo(VF.createIRI("urn:first"));
			});
		}

		QueryBindingSet incompatible = input();
		incompatible.addBinding("innerO", VF.createLiteral(11));
		try (var results = strategy.evaluateTripleRefJoinGroup(group, incompatible)) {
			assertThat(QueryResults.asList(results)).isEmpty();
		}
	}

